/*
 * A256867  Numbers divisible by prime(d+1) for each digit d of their base-7
 *          representation.
 * https://oeis.org/A256867
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the nth non‑negative integer such that for every base‑7
 *            digit d the integer is divisible by prime(d+1). (prime(1)=2,
 *            prime(2)=3, …, prime(7)=17). The sequence is generated by
 *            exhaustive search
 * Range:     u8 n <= 6, u16 n <= 212, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* 7th primes corresponding to digits 0…6 */
static const int primes[7] = {2,3,5,7,11,13,17};

/* Test whether a number satisfies the divisibility property. */
static bool passes(seq_t v)
{
    if (v == 0) return true;          /* 0 is divisible by everything */

    seq_t tmp = v;
    while (tmp != 0)
    {
        int d = (int)(tmp % 7);        /* current base–7 digit */
        if (v % primes[d] != 0)        /* divisibility check */
            return false;
        tmp /= 7;
    }
    return true;
}

/* Cache for previously found terms */
static seq_t *cache   = NULL;
static size_t cache_len = 0, cache_cap = 0;
static seq_t next_value = 0;           /* next integer to test */

/* Ensure cache has at least n terms. */
static void ensure_cache(idx_t n)
{
    if (cache_len == 0)                /* first use: initialise cache */
    {
        cache_cap = 16;
        cache = (seq_t *)realloc((void *)cache, cache_cap * sizeof(seq_t));
        cache[0] = 0;                  /* a(1) = 0 */
        cache_len = 1;
        next_value = 1;                /* start searching from 1 */
    }

    while (cache_len < n)
    {
        seq_t candidate = next_value;
        if (passes(candidate))
        {
            if (cache_len == cache_cap)
            {
                size_t new_cap = cache_cap * 2;
                seq_t *tmp = (seq_t *)realloc((void *)cache, new_cap * sizeof(seq_t));
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = candidate;
        }
        ++next_value;
    }
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (n < 1) return 0;               /* undefined for n<1, return 0 */
    ensure_cache(n);
    return cache[n-1];
}
